import Foundation

/// Loads cross-language fixtures from `Tests/Fixtures/*.json`.
/// Fixtures are generated by `Scripts/vectors/gen-fixtures.mjs` from the
/// built sdk-js packages; see `Tests/Fixtures/README.md`.
public enum Fixtures {
    public static var directory: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()  // ZeroXKeyTestSupport
            .deletingLastPathComponent()  // Tests
            .appendingPathComponent("Fixtures")
    }

    public static func load<T: Decodable>(_ name: String, as type: T.Type = T.self) throws -> T {
        let data = try Data(contentsOf: directory.appendingPathComponent("\(name).json"))
        return try JSONDecoder().decode(T.self, from: data)
    }

    public static func json(_ name: String) throws -> [String: Any] {
        let data = try Data(contentsOf: directory.appendingPathComponent("\(name).json"))
        guard let obj = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            throw CocoaError(.fileReadCorruptFile)
        }
        return obj
    }
}

/// `_meta` header present in every fixture.
public struct FixtureMeta: Decodable, Sendable {
    public let generator: String
    public let sdk_js_commit: String
    public let fixture: String
}

public struct KeyPairFixture: Decodable, Sendable {
    public let privateKey: String
    public let publicKey: String
    public let publicKeyUncompressed: String
}
